package com.forgedprogression.client;

import com.forgedprogression.ForgedProgression;
import net.minecraft.client.renderer.texture.TextureAtlasSprite;
import net.minecraft.client.resources.IResourceManager;
import net.minecraft.util.ResourceLocation;

import java.awt.image.BufferedImage;
import java.util.function.Function;

/** Atlas sprite (item/block icon) generated by recoloring a vanilla texture instead of loading a PNG. */
public class RecoloredSprite extends TextureAtlasSprite {

    private final Recolor.Spec spec;

    public RecoloredSprite(String name, Recolor.Spec spec) {
        super(name);
        this.spec = spec;
    }

    @Override
    public boolean hasCustomLoader(IResourceManager manager, ResourceLocation location) {
        return true;
    }

    /** @return false on success; true tells the atlas to skip this sprite. */
    @Override
    public boolean load(IResourceManager manager, ResourceLocation location,
                        Function<ResourceLocation, TextureAtlasSprite> textureGetter) {
        try {
            BufferedImage img = spec.render(manager);
            int w = img.getWidth();
            int h = Math.min(img.getHeight(), w); // animated/strip textures: use the first frame
            int[][] frame = new int[17][];        // room for every mipmap level; filled in later by the atlas
            frame[0] = new int[w * h];
            img.getRGB(0, 0, w, h, frame[0], 0, w);

            setIconWidth(w);
            setIconHeight(h);
            clearFramesTextureData();
            framesTextureData.add(frame);
            return false;
        } catch (Exception e) {
            ForgedProgression.LOGGER.error("Could not build recolored texture {} from {}", getIconName(), spec.source, e);
            return true;
        }
    }
}
